# Bad: mutation
def add_tax(prices: list[int], rate: float) -> list[int]:
    for i in range(len(prices)):
        prices[i] = int(prices[i] * (1.0 + rate))
    return prices

# Good: pure, immutable, single responsibility
def add_tax(price: int, rate: float) -> int:
    return int(price * (1.0 + rate))

def iter_add_tax(prices: Iterable[int], rate: float) -> Iterator[int]:
    return (add_tax(p, rate) for p in prices)

def add_tax_to_prices(prices: tuple[int, ...], rate: float) -> tuple[int, ...]:
    return tuple(iter_add_tax(prices, rate))
```

