### Functions

```python
# Bad: nested, long, multiple responsibilities
def process(data):
    result = []
    for item in data:
        if item > 0:
            for i in range(item):
                if i % 2 == 0:
                    result.append(i * 2)
    return result

# Good: small, single responsibility, Never Nester
def _is_even(n: int) -> bool:
    return n % 2 == 0

def _evens_integers(integers: Iterable[int]) -> Iterator[int]:
    return (i for i in integers if _is_even(i))

def _double(n: int) -> int:
    return n * 2

def _double_ints(integers: Iterable[int]) -> Iterator[int]:
    return (_double(i) for i in integers)

def double_positive_evens(integers: Sequence[int, ...]) -> Iterator[int, ...]:
    return (_double_ints(_evens_integers(integers)))
```

### Ordering

```python
# Callee-first: helpers appear before their first caller

def _validate(x: int) -> int:
    if x < 0:
        raise ValueError("negative not allowed")
    return x

def _transform(x: int) -> int:
    return x * 2

def valid_transform(x: int) -> int:
    return _transform(_validate(x))

def main() -> int:
    return valid_transform(5)
```

