from typing import Iterable, Sequence, Mapping
from collections.abc import Iterator

# Prefer generic for parameters
def sum_values(nums: Iterable[int]) -> int:  # Not list[int]
    return sum(nums)

def first[T](items: Sequence[T]) -> T:  # When indexing needed
    return items[0]

def lookup(mapping: Mapping[str, int], key: str) -> int:  # Not dict
    return mapping[key]
