### Return type contracts

```python
from typing import Iterator

# Streaming contract → Iterator[T]
def iter_lines(path: Path) -> Iterator[str]:
    with path.open() as f:
        yield from f

# Materialised contract → tuple/frozenset
def get_unique_ids(orders: Iterable[Order]) -> frozenset[str]:
    return frozenset(o.order_id for o in orders)

# Only use list when contract requires it
def get_sorted_ids(orders: Iterable[Order]) -> list[str]:
    return sorted(o.order_id for o in orders)
