# Bad: try/except in business logic
def process_file(path: Path) -> str:
    try:
        with path.open() as f:
            return f.read().upper()
    except FileNotFoundError as e:
        raise ValueError(f"Config not found: {path}") from e

# Ok: exception handling in dedicated helper
def _read_file_or_raise(path: Path) -> str:
    try:
        return path.read_text()
    except FileNotFoundError as e:
        raise ValueError(f"Config not found: {path}") from e

def process_file(path: Path) -> str:
    return _read_file_or_raise(path).upper()

# Good: add context with add_note (one statement in except)
def _add_note(e: Exception, note: str) -> Exception:
    e.add_note(note)
    return e

def validate_config(data: str) -> None:
    try:
        _parse_config(data)
    except ValueError as e:
        raise _add_note(e, "Invalid config format")
```
